defaultBranch.query:
query RunStatusDefaultBranch($owner: String!, $name: String!) {
  repository(owner: $owner, name: $name) {
    defaultBranchRef { name }
  }
}

mergeCommit.query:
query RunStatusMergeCommit($owner: String!, $name: String!) {
  repository(owner: $owner, name: $name) {
    pr2487: pullRequest(number: 2487) {
      number state
      mergeCommit { oid }
    }
  }
}
